import java.io.*;

public class Main {
    static List<String> analyze(int n, int[][] records) {
        // Write your solution here
        // Return the lines to print: ["INVALID"] or ["VALID", "COMPLETE" / "INCOMPLETE", first, last]
        return new ArrayList<>();
