    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] records = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); records[i][0] = (int) in.nval;
            in.nextToken(); records[i][1] = (int) in.nval;
        }
        StringBuilder sb = new StringBuilder();
        for (String line : analyze(n, records)) sb.append(line).append("\n");
        System.out.print(sb);
    }
}
